<template>
  <view class="patient-detail">
    <view class="nav-header">
      <view class="back-btn" @click="goBack">
        <text class="back-icon">&#xe60e;</text>
        <text>返回</text>
      </view>
      <view class="page-title">患者详情</view>
    </view>
    
    <view class="card basic-info">
      <view class="card-title">基本信息</view>
      <view class="info-row">
        <view class="info-label">姓名</view>
        <view class="info-value">{{ patient.name }}</view>
      </view>
      <view class="info-row">
        <view class="info-label">年龄</view>
        <view class="info-value">{{ patient.age }}岁</view>
      </view>
      <view class="info-row">
        <view class="info-label">性别</view>
        <view class="info-value">{{ patient.gender }}</view>
      </view>
      <view class="info-row">
        <view class="info-label">身份</view>
        <view class="info-value">{{ patient.identity }}</view>
      </view>
      <view class="info-row">
        <view class="info-label">预约时间</view>
        <view class="info-value">{{ patient.appointmentTime }}</view>
      </view>
    </view>
    
    <view class="card medical-history">
      <view class="card-title">既往病史</view>
      <view class="medical-history-content">
        {{ patient.medicalHistory || '无' }}
      </view>
    </view>
    
    <view class="card previous-visits">
      <view class="card-title">就诊记录</view>
      <view v-if="patient.previousVisits && patient.previousVisits.length > 0">
        <view v-for="(visit, index) in patient.previousVisits" :key="index" class="visit-item">
          <view class="visit-date">{{ visit.date }}</view>
          <view class="visit-info">
            <text class="visit-department">{{ visit.department }}</text>
            <text class="visit-doctor">{{ visit.doctor }}</text>
          </view>
        </view>
      </view>
      <view v-else class="empty-visits">
        无历史就诊记录
      </view>
    </view>
    
    <view class="action-buttons">
      <button 
        class="action-btn" 
        :class="{ 'btn-disabled': patient.status === 'completed' }"
        @click="updateStatus('in-progress')"
        :disabled="patient.status === 'completed'"
      >
        标记为已接诊
      </button>
      <button 
        class="action-btn" 
        :class="{ 'btn-disabled': patient.status !== 'in-progress' }"
        @click="updateStatus('completed')"
        :disabled="patient.status !== 'in-progress'"
      >
        标记为已完成
      </button>
    </view>
  </view>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import { uniShowToast, uniNavigateBack, uniNavigateTo } from '@/utils/uniHelper';

const patient = ref({});

onMounted(() => {
  // 从URL参数中获取患者信息
  const pages = getCurrentPages();
  const currentPage = pages[pages.length - 1];
  const patientInfo = currentPage.$page.options.patient;
  
  if (patientInfo) {
    try {
      patient.value = JSON.parse(decodeURIComponent(patientInfo));
    } catch (e) {
      console.error('解析患者信息失败', e);
    }
  }
});

const updateStatus = async (status) => {
  // 模拟API调用更新患者状态
  setTimeout(async () => {
    patient.value.status = status;
    
    let message = '';
    if (status === 'in-progress') {
      message = '已标记为接诊中';
    } else if (status === 'completed') {
      message = '已标记为就诊完成';
    }
    
    await uniShowToast({ title: message });
  }, 500);
};

const goBack = () => {
  uniNavigateBack(); // 使用uniNavigateBack返回上一页，即患者列表页面
};
</script>

<style scoped>
.patient-detail {
  min-height: 100vh;
  background-color: #f5f7fa;
  padding-bottom: 120rpx;
}

.nav-header {
  position: relative;
  height: 90rpx;
  background-color: #1677ff;
  color: #fff;
  display: flex;
  align-items: center;
  padding: 0 30rpx;
}

.back-btn {
  position: absolute;
  left: 30rpx;
  display: flex;
  align-items: center;
  font-size: 28rpx;
}

.back-icon {
  font-family: "iconfont";
  margin-right: 6rpx;
}

.page-title {
  width: 100%;
  text-align: center;
  font-size: 32rpx;
  font-weight: 500;
}

.card {
  background-color: #fff;
  border-radius: 16rpx;
  padding: 30rpx;
  margin: 30rpx;
  box-shadow: 0 2rpx 10rpx rgba(0, 0, 0, 0.05);
}

.card-title {
  font-size: 32rpx;
  font-weight: bold;
  color: #333;
  margin-bottom: 20rpx;
  border-bottom: 2rpx solid #f0f0f0;
  padding-bottom: 16rpx;
}

.info-row {
  display: flex;
  margin-bottom: 16rpx;
}

.info-label {
  width: 160rpx;
  font-size: 28rpx;
  color: #666;
}

.info-value {
  flex: 1;
  font-size: 28rpx;
  color: #333;
}

.medical-history-content {
  font-size: 28rpx;
  color: #333;
  line-height: 1.6;
}

.visit-item {
  padding: 20rpx 0;
  border-bottom: 2rpx solid #f0f0f0;
}

.visit-item:last-child {
  border-bottom: none;
}

.visit-date {
  font-size: 26rpx;
  color: #999;
  margin-bottom: 10rpx;
}

.visit-info {
  display: flex;
  justify-content: space-between;
}

.visit-department, .visit-doctor {
  font-size: 28rpx;
  color: #333;
}

.empty-visits {
  font-size: 28rpx;
  color: #999;
  text-align: center;
  padding: 30rpx 0;
}

.action-buttons {
  display: flex;
  justify-content: space-between;
  padding: 0 30rpx;
  margin-top: 20rpx;
}

.action-btn {
  width: 48%;
  height: 88rpx;
  line-height: 88rpx;
  border-radius: 44rpx;
  font-size: 30rpx;
  background-color: #1677ff;
  color: #fff;
}

.btn-disabled {
  background-color: #a5c8ff;
}
</style>